"""Stage one of Ps 17 (17:2–17:25), draft 1 → ps017/prayed.json.
python3.13 research/psalterium/ps017/build_v1.py
Written as a script so that the options are built with one helper and the JSON cannot be malformed."""
import json
from pathlib import Path

here = Path(__file__).resolve().parent


def opt(label, forms, note, source='draft'):
    return {'label': label, 'forms': forms, 'note': note, 'from': source}


def dec(id, refs, latin, kind, why, options):
    return {'id': id, 'refs': refs, 'latin': latin, 'kind': kind, 'why': why, 'options': options}


